import json,hashlib,statistics,re
r=Path.cwd();o=r/'.work/stack-check-selection-20261116';h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
plan=r/'.work/vm-all-validation-20261115/plan.json';p=json.loads(plan.read_text());definitions={x['case']:x['config']['definition'] for x in p['items']};extra=r/'.work/vm-priority-validation-20261115/linux-nobt-config.json';definitions['catch/nobt-throw']=json.loads(extra.read_text())['definition'];assert len(definitions)==17
hits={word:[k for k,v in definitions.items() if word in v.upper().split()] for word in ['2R>','DNEGATE']}
rows=[];sources={}
