   for j,k in enumerate(order):
    q=x['process_time_queries'][n*2+j]['queries'];first,last=q[:2];kernel=(last['kernel_ns']-first['kernel_ns'])/1e6;user=(last['user_ns']-first['user_ns'])/1e6;cpu=kernel+user;thread=sum(last['primary_thread'][a]-first['primary_thread'][a] for a in ['kernel_ns','user_ns'])/1e6
    if n:
     index=indices[k];expected=x['engines'][k]['samples_us'][index]/1000;assert abs(cpu-expected)<1e-7,(case,i,k,index,cpu,expected);indices[k]+=1;audit+=1
     values[k].append({'cpu_ms':cpu,'kernel_ms':kernel,'user_ms':user,'cycles':last['cycles']-first['cycles'],'wall_ms':x['engines'][k]['wall_samples_us'][index]/1000,'process_minus_primary_thread_ms':cpu-thread})
  medians={k:{a:statistics.median(v[a] for v in vs) for a in ['cpu_ms','kernel_ms','user_ms','cycles','wall_ms']} for k,vs in values.items()};delta=lambda a:100*abs(medians['A1'][a]-medians['A2'][a])/min(medians['A1'][a],medians['A2'][a]);rows.append({'case':case,'series':i,'medians':medians,'AA_delta_percent':{a:delta(a) for a in ['cpu_ms','wall_ms','cycles']},'audited_counted_samples':audit,'max_abs_process_minus_primary_thread_ms':max(abs(v['process_minus_primary_thread_ms']) for vs in values.values() for v in vs),'samples':values})
asm={name:(r/'.work/stack-check-20261116'/f).read_text(encoding='utf-8') for name,f in [('2R>','execute__func_491.asm'),('DNEGATE','execute__func_444.asm')]}
report={'decision':'Both retained as reserve; do not start another trial until measurement stability and workload relevance are assessed. No claim on relative speed benefit.','definitions':definitions,'direct_token_hits':hits,'scope_note':'17 distinct kernel definition strings from 29 items plus the reused nobt configuration. Lexical search only, not transitive dynamic word frequency.','benchmark_plan_sha256':h(plan),'reused_nobt_config_sha256':h(extra),'source_hashes':{f:h(r/f) for f in ['src/forth.zig','src/core/words_stack.zig','src/core/words_arithmetic.zig']},'baseline_assembly':asm,'assembly_scope':'reused Linux fast baseline-CPU uncounted symbols, addresses from previous artifacts; Windows/counted not checked','timing_input_hashes':sources,'timing_rows':rows,'limitations':['No candidate comparison was performed in these files','CPU median is not sum of separately calculated kernel/user medians','Cycle counts are neither elapsed time nor retired instruction counts','No causal conclusion on kernel accounting or hardware','A/A percent is not a confidence interval','Thread equality only applies to these 40 counted samples']}
(r/'docs/measurements/2026-11-16-stack-check-selection.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
(o/'summary.json').write_text(json.dumps({'hits':hits,'timing':[{k:v for k,v in x.items() if k not in ['samples','medians']} for x in rows]},indent=2)+'\n');print((o/'summary.json').read_text())
